t.script:
var slotUserMap = {


            "": [

                    {"id": , "name": "", "capacity": },

            ],


};

document.addEventListener('DOMContentLoaded', function() {
    var radios = document.querySelectorAll('input[name="time"]');
    var staffContainer = document.getElementById('staff_selection_container');
    var staffOptions = document.getElementById('staff_selection_options');
    var hiddenStaffInput = document.getElementById('selected_staff_id');

    function updateStaff() {
        var selectedTime = document.querySelector('input[name="time"]:checked');
        if (!selectedTime) return;

        var users = slotUserMap[selectedTime.value] || [];
        var partySizeSelect = document.querySelector('select[name="party_size"]');
        var selectedPartySize = partySizeSelect ? parseInt(partySizeSelect.value) : 1;

        staffOptions.innerHTML = '';

        var validUsers = users.filter(u => u.capacity >= selectedPartySize);

        if (validUsers.length > 0) {
            staffContainer.style.display = 'block';
            var noPrefHtml = `






                             No Preference



            `;
            staffOptions.innerHTML += noPrefHtml;

            validUsers.forEach(function(u) {
                var html = `








                                    ${u.name.charAt(0).toUpperCase()}

                                ${u.name}



                `;
                staffOptions.innerHTML += html;
            });

            var staffRadios = document.querySelectorAll('input[name="staff_user_id_radio"]');
            staffRadios.forEach(function(r) {
                r.addEventListener('change', function() {
                    hiddenStaffInput.value = this.value;
                });
            });
            hiddenStaffInput.value = "";
        } else {
            staffContainer.style.display = 'none';
            hiddenStaffInput.value = "";
        }
    }

    radios.forEach(function(r) {
        r.addEventListener('change', updateStaff);
    });
    var partySizeSelect = document.querySelector('select[name="party_size"]');
    if (partySizeSelect) {
        partySizeSelect.addEventListener('change', updateStaff);
    }

    updateStaff();
});
